Fixpoint itab_of_ranges (rs : list (Z * nat)) (t : itab) : itab :=
  match rs with
  | [] => t
  | (lo, n) :: rs' => itab_of_ranges rs' (mk_itab_fuel segs n lo t)
  end.
Lemma itab_of_ranges_sound : forall rs t, itab_sound segs t -> itab_sound segs (itab_of_ranges rs t).
